/* ===================== drawers v3: renderDrawer() + openXxx renderers (return {title,status,body,footer}) ===================== */
/* small helpers core.js lacks (kept local to this file) */
const REF_COLS={PO:"purchases",SH:"shipments",PAY:"payments",IN:"inspections",RC:"receipts",MV:"moves",CN:"credits",IMP:"imports"};
function colOfRef(ref){ref=String(ref||"");for(const[col,n]of Object.entries(SET().numbering||{})){if(n?.pfx&&ref.startsWith(n.pfx+"-"))return col}const pfx=ref.split("-")[0];if(REF_COLS[pfx])return REF_COLS[pfx];for(const col of Object.keys(REF_COLS)){if((D[REF_COLS[col]]||[]).some(x=>x.no===ref))return REF_COLS[col]}return null}
function docOf(col,v){if(v&&typeof v==="object")return v;return(D[col]||[]).find(x=>(x.no||x.id)===v||x.id===v||x.code===v||x.sku===v)}
function userName(id){if(!id)return"—";const u=(SET().users||[]).find(u=>u.uid===id);if(u)return u.name;const p=person(id);return p?p.name:id==="local"?"this device":String(id)}
oldRefs=x=>[].concat(x?.oldRef||[]).filter(Boolean).map(String).join(", ");
const v_=x=>x==null||x===""?"—":esc(x);
const pct=(x,d=0)=>x==null||isNaN(+x)?"—":num(x,d)+"%";
const maskIf=x=>can("bank")?v_(x):(x?"•••":"—");
const alink=(u,l)=>u?`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(l||u)}</a>`:"";
const blobUrl=id=>window.__blobUrl?window.__blobUrl(id):`/_blob/${encodeURIComponent(id)}`;
const isImgAsset=(id,name)=>!/\.pdf$/i.test(String(name||id||""));
pill=(text,cls)=>`<span class="pill ${cls||"p-mute"}">${esc(text)}</span>`;
const mi=(label,attrs,sub,cls)=>`<button ${attrs}${cls?` class="${cls}"`:""}>${esc(label)}${sub?`<small>${esc(sub)}</small>`:""}</button>`;
const sec=(title,html,right)=>`<div class="sec"><h3>${esc(title)}${right?`<span class="status">${right}</span>`:""}</h3>${html}</div>`;
const note=t=>`<div class="note">${esc(t)}</div>`;
function kv(pairs){const rows=(pairs||[]).filter(p=>p&&p[1]!=null&&p[1]!==false);if(!rows.length)return"";return`<div class="kv">${rows.map(([l,val,sub])=>`<div><span>${esc(l)}</span><b>${val===""?"—":val}</b>${sub?`<small class="status" style="display:block">${sub}</small>`:""}</div>`).join("")}</div>`}
function tbl(heads,rows,foot){if(!rows.length)return"";const th=heads.map(h=>{const o=typeof h==="string"?{l:h}:h;return`<th${o.n?' class="n"':""}>${esc(o.l)}</th>`}).join("");const tr=r=>`<tr>${r.map((c,i)=>{const o=typeof heads[i]==="string"?{}:heads[i]||{};return`<td${o.n?' class="n"':""}>${c==null||c===""?"—":c}</td>`}).join("")}</tr>`;return`<div class="tbl"><table><thead><tr>${th}</tr></thead><tbody>${rows.map(tr).join("")}</tbody>${foot?`<tfoot>${foot.map(r=>`<tr>${r.map((c,i)=>{const o=typeof heads[i]==="string"?{}:heads[i]||{};return`<th${o.n?' class="n"':""}>${c??""}</th>`}).join("")}</tr>`).join("")}</tfoot>`:""}</table></div>`}
/* clickable reference chip: label is always a human label (no raw ids) */
function refChip(col,id,label){if(!id)return"—";const x=docOf(col,id);const text=label||(col==="products"?(x?.name||id):col==="parties"?(x?.name||id):String(id));if(!x)return`<span class="chip" title="not found">${esc(text)}</span>`;return`<button class="chip" data-open="${esc(col)}" data-id="${esc(x.no||x.code||x.sku||x.id)}" title="${esc(label&&col!=="products"&&col!=="parties"?id:(col==="products"?x.sku:col==="parties"?x.code:""))}">${esc(text)}${x.deletedAt?" 🗑":""}</button>`}
const anyRef=ref=>{const col=colOfRef(ref);return col?refChip(col,ref):v_(ref)};
const prodChip=sku=>sku?refChip("products",sku,product(sku)?`${product(sku).name} · ${sku}`:sku):"—";
const partyChip=code=>code?refChip("parties",code,pname(code)):"—";
function refBox(text){if(!text)return"";return`<div class="refbox"><span>${esc(text)}</span><button class="btn sm" data-act="copytext" data-text="${esc(text)}" aria-label="Copy reference text">Copy</button></div>`}
function stepper(listKey,cur){const all=items(listKey,{all:true});const steps=all.filter(i=>(+i.step||0)>=0&&!(i.archived&&i.id!==cur)).sort((a,b)=>(+a.step)-(+b.step));const it=all.find(i=>i.id===cur);if(it&&(+it.step)<0)return`<div>${pill(it.label,"p-bad")}</div>`;const idx=steps.findIndex(s=>s.id===cur);return`<div class="steps" role="list" aria-label="Progress">${steps.map((s,i)=>`<div class="st ${i<idx?"d":i===idx?"c":""}" role="listitem"${i===idx?' aria-current="step"':""}><i>${i<idx?"✓":i+1}</i><span>${esc(s.label)}</span></div>`).join("")}${idx<0&&cur?`<div class="status">Status "${esc(cur)}" is not in Setup › Lists</div>`:""}</div>`}
/* custom fields from Setup › Forms, shown on every drawer */
function customVal(f,v){if(v==null||v==="")return null;if(f.t==="list")return L(f.list,v);if(f.t==="bool")return v===true||v==="true"?"Yes":"No";if(f.t==="date")return fmtD(v);if(f.t==="link")return null;if(f.t==="opts"){const o=(f.opts||[]).find(x=>String(Array.isArray(x)?x[0]:x)===String(v));return o?(Array.isArray(o)?o[1]:o):String(v)}return String(v)}
function customBlock(form,x){const cf=(typeof fields==="function"?fields(form):[]).filter(f=>f.custom);const c=x?.custom||{};const pairs=cf.map(f=>{const v=c[f.k];if(v==null||v==="")return null;if(f.t==="link")return[f.l||f.k,alink(v,"Open")];return[f.l||f.k,esc(customVal(f,v))]}).filter(Boolean);
 /* values saved under a field that was since removed from Setup are still shown */Object.keys(c).filter(k=>!cf.some(f=>f.k===k)&&c[k]!=null&&c[k]!=="").forEach(k=>pairs.push([k,esc(String(c[k]))]));return pairs.length?sec("More fields",kv(pairs)):""}
function relatedBlock(col,id){const rel=relatedDocs(col,id);if(!rel.length)return"";return sec("Related documents",`<div class="related">${rel.map(r=>`<button data-open="${esc(r.col)}" data-id="${esc(r.id)}">${esc(r.col==="products"?r.x?.name||r.id:r.col==="parties"?pname(r.id):r.id)}${r.x?.deletedAt?" 🗑":""}<small>${esc(r.why)}</small></button>`).join("")}</div>`)}
function docTypesFor(col){return items("docType").filter(t=>{const f=Array.isArray(t.for)?t.for:typeof t.for==="string"?t.for.replace(/[\[\]"']/g,"").split(/[,\s]+/):[];return f.includes(col)})}
function docsBlock(col,x,opts={}){const types=docTypesFor(col).filter(t=>!(opts.skip||[]).includes(t.id));if(!types.length)return"";const id=x.no||x.id;const have=x.docs||{};
 const rows=types.map(t=>{const d=have[t.id];const url=d?.url||(typeof d==="string"?d:null);const asset=d?.assetId||d?.asset;const ok=!!(url||asset);const iid=`dl_${esc(id)}_${esc(t.id)}`.replace(/[^\w-]/g,"_");
  return`<div class="att" style="padding:7px 0;gap:8px"><span aria-hidden="true" style="color:${ok?"var(--ok)":"var(--muted)"}">${ok?"✓":"○"}</span><div class="t"><b>${esc(t.label)}</b>${ok?`<div>${url?alink(url,"Open link"):""}${asset?` ${alink(blobUrl(asset),"Open file")}`:""}${d?.at?` · ${esc(fmtD(d.at))}${d.by?" · "+esc(userName(d.by)):""}`:""}</div>`:`<div class="inl"><input id="${iid}" type="url" placeholder="Paste link" aria-label="${esc(t.label)} link" data-act="doclink" data-col="${esc(col)}" data-id="${esc(id)}" data-doc="${esc(t.id)}"><button class="btn sm" data-act="doclink" data-col="${esc(col)}" data-id="${esc(id)}" data-doc="${esc(t.id)}" data-input="#${iid}">Add</button><label class="btn sm">Upload<input type="file" hidden accept="image/*,application/pdf" aria-label="Upload ${esc(t.label)}" data-act="docfile" data-col="${esc(col)}" data-id="${esc(id)}" data-doc="${esc(t.id)}"></label></div>`}</div></div>`}).join("");
 return sec("Documents",rows,`${types.filter(t=>have[t.id]&&(have[t.id].url||have[t.id].assetId||have[t.id].asset||typeof have[t.id]==="string")).length}/${types.length}`)}
function tagsBlock(x){const tags=(x.tags||[]).filter(Boolean);if(!tags.length)return"";return sec("Tags",`<div>${tags.map(t=>`<span class="tagc">${esc(L("tag",t))}</span>`).join("")}</div>`)}
function notesBlock(x){const parts=[];if(x.notes)parts.push(`<div class="note">${esc(x.notes)}</div>`);if(x.desc&&x.desc!=="(see notes)"&&!(x.lines||[]).length)parts.push(`<div class="note">${esc(x.desc)}</div>`);{const g=x.goodsAuto&&(x.lines||[]).length&&typeof shipGoodsText==="function"?shipGoodsText(x)||x.goods:x.goods;if(g)parts.push(`<div class="note"><b>Goods:</b> ${esc(g)}</div>`)}if(x.source)parts.push(`<div class="note status">Source: ${esc(x.source)}</div>`);if(!parts.length)return"";return sec("Notes",parts.join(""))}
function linksBlock(links,extra){const all=[...(extra||[]),...(links||[]).map(l=>({label:l.label,url:l.url}))].filter(l=>l&&(l.url||l.html));if(!all.length)return"";return sec("Links",`<div class="note">${all.map(l=>l.html||alink(l.url,l.label||l.url)).join(" · ")}</div>`)}
function folderLine(x,col){const name=folderName(x,col);return{html:`Drive folder name: <span class="num">${esc(name)}</span> <button class="btn sm" data-act="copytext" data-text="${esc(name)}" aria-label="Copy folder name">Copy</button>`}}
function auditLine(x){const bits=[];if(x.createdAt)bits.push(`Created ${esc(fmtDL(x.createdAt))} by ${esc(userName(x.createdBy))}`);if(x.updatedAt&&x.updatedAt!==x.createdAt)bits.push(`updated ${esc(fmtDL(x.updatedAt))} by ${esc(userName(x.updatedBy))}`);if(x.historic)bits.push(pill("Imported legacy record","p-mute"));if(x.deletedAt)bits.push(`in Trash since ${esc(fmtDL(x.deletedAt))}`);return bits.length?`<div class="status">${bits.join(" · ")}</div>`:""}
function trashBox(col,x){if(!x?.deletedAt)return"";const days=Math.max(0,(DEF().trashDays||30)-diffDays(x.deletedAt.slice(0,10),today()));return`<div class="warnbox" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><span style="flex:1">In Trash — ${days} day${days===1?"":"s"} left before it is removed</span><button class="btn sm" data-act="restore" data-col="${esc(col)}" data-id="${esc(x.no||x.id)}">Restore</button></div>`}
function footerBtns(primary,more){const pri=(primary||[]).filter(Boolean);const main=pri.slice(0,3);const rest=[...pri.slice(3).map(b=>b.replace(/class="btn[^"]*"/,"")),...(more||[]).filter(Boolean)];return`${main.join("")}${rest.length?`<div class="morem"><button class="btn" data-act="moremenu" aria-haspopup="true" aria-expanded="false" aria-controls="moremenu">More ▾</button><div class="menu" id="moremenu" hidden role="menu">${rest.join("")}</div></div>`:""}`}
function statusMenu(listKey,col,id,cur){const its=items(listKey).filter(i=>!i.archived||i.id===cur);if(!its.length)return"";return`<h6>Set status</h6>${its.map(i=>mi(`${i.id===cur?"✓ ":""}${i.label}`,`data-act="setstatus" data-col="${esc(col)}" data-id="${esc(id)}" data-status="${esc(i.id)}" role="menuitem"`)).join("")}`}
const trashItem=(col,id)=>can("deleteAny")?mi("Move to Trash",`data-act="trash" data-col="${esc(col)}" data-id="${esc(id)}" role="menuitem"`,null,"danger"):"";
const editBtn=(col,id,label)=>`<button class="btn" data-act="edit" data-col="${esc(col)}" data-id="${esc(id)}">${esc(label||"Edit")}</button>`;
const poCls=s=>["hold","cancelled"].includes(s)?"p-bad":["closed","received"].includes(s)?"p-ok":s==="draft"?"p-mute":"p-info";
const shCls=s=>s==="delivered"?"p-ok":s==="cancelled"?"p-bad":["arrived","part_delivered"].includes(s)?"p-warn":"p-info";
const inspCls=r=>r==="pass"?"p-ok":r==="pass_remarks"?"p-warn":r==="fail"?"p-bad":"p-mute";
const payLabelCls=t=>t==="Paid"||t==="Paid (no PI)"?"p-ok":t==="Overpaid"?"p-warn":t==="Part paid"?"p-info":t==="Unpaid"?"p-bad":"p-mute";
const dueCls=(due,paid)=>paid?"p-ok":due&&due<today()?"p-bad":"p-info";
function paidIn(pay,ref,cur){const a=allocAmount(pay,ref)*paySignOf(pay);if(pay.cur===cur)return a;const r=payRate(pay),rc=rateOn(today(),cur);return r==null||rc==null?0:a*r/rc}
/* payment rows: counted ones move the balance; the others are listed with why they do not count */
/* ---------- mixed invoices / payments (core: poSplit, poViaRows, isOtherAlloc, recharges) ---------- */
function orefChip(r){const inf=orefInfo(r);if(!inf)return"";if(inf.t==="doc")return refChip(inf.col,inf.id);if(inf.t==="party")return partyChip(inf.id);return`<b>${esc(inf.label)}</b>`}
const payOthers=x=>(x?.allocations||[]).filter(isOtherAlloc);
/* "¥25,781.00 sent · ¥24,416.50 for this order · ¥1,364.50 for PO-26-0067 (no fee)" */
function paySplitLine(x,ref){const oth=payOthers(x);const mine=(x.allocations||[]).find(a=>a.ref===ref);if(!ref)return"";
 if(mine&&isOtherAlloc(mine)){const m=mainAllocOf(x);return`<br><small class="status mixline">sent with the ${m?esc(m.ref):"another"} payment (${esc(fmt(x.amount,x.cur))} sent)${mine.note?" — "+esc(mine.note):""}</small>`}
 if(!oth.length)return"";const forMe=allocAmount(x,ref);return`<br><small class="status mixline">${esc(fmt(x.amount,x.cur))} sent · ${esc(fmt(forMe,x.cur))} for this · ${oth.map(a=>`${esc(fmt(a.amount,x.cur))} for ${a.oref||a.ref?orefChip(a.oref||a.ref)+" ":""}${esc(coLabel(a.belongsTo))}${a.note?" — "+esc(a.note):""} (no fee)`).join(" · ")}</small>`}
/* Recharge rows (Reports, party drawer): who owes us / which company or brand should bear it; personal flagged */
function rechargeTable(rows){return tbl(["Date","Paid on","For","What",{l:"Amount",n:1},{l:"£",n:1}],rows.map(r=>[fmtD(r.date),`${refChip(r.col,r.src)}${r.with?`<br><small class="status">with ${esc(r.with)}</small>`:""}`,`${r.ref?orefChip(r.ref)+"<br>":""}${pill(coLabel(r.belongsTo),r.personal?"p-bad":"p-warn")}${r.personal?' <small class="status">personal / non-business</small>':""}`,`<small class="status">${esc(String(r.label||"").slice(0,80))}${r.note&&r.note!==r.label?" — "+esc(String(r.note).slice(0,80)):""}</small>`,`${fmt(r.amount,r.cur)}${r.fee?'<br><small class="status">incl. China fee</small>':'<br><small class="status">no fee</small>'}`,r.gbp==null?"—":gbp(r.gbp)]))}
function invoiceBreakdown(p,st){const cur=p.cur||"RMB";const sp=poSplit(p);const T=a=>esc(fmt(a,cur));
 const parts=[`products ${T(sp.lines)}`];if(sp.extras)parts.push(`extras ${T(sp.extras)}`);if(sp.fee)parts.push(sp.feeFromRows?`China fee ${T(sp.fee)} (fee line on the PI${sp.feeBase?` = ${num(sp.feePct,2)}% of ${T(sp.feeBase)}`:""})`:`China fee ${num(sp.feePct,2)}% on ${T(sp.feeBase)} = ${T(sp.fee)}`);if(sp.diff)parts.push(`difference to the PI total ${T(sp.diff)}`);
 const oth=sp.others.map(o=>`<li>${T(o.amount)} for ${o.ref?orefChip(o.ref)+" ":""}<small class="status">${esc(coLabel(o.belongsTo))} · ${esc(o.label)}${o.note?" — "+esc(String(o.note).slice(0,100)):""}</small> ${o.fee?pill(`fee ${fmt(o.feeAmt,cur)} charged on it`,"p-warn"):pill("no fee","p-mute")}</li>`);
 const via=st.via.map(v=>`<li>${esc(fmt(v.amt,v.cur))} billed on the ${refChip("purchases",v.from)} invoice <small class="status">${esc(v.label)}${v.note?" — "+esc(String(v.note).slice(0,100)):""}</small> ${v.fee?"":pill("no fee","p-mute")}</li>`);
 const payOther=[];st.pays.filter(Boolean).forEach(x=>{if((x.allocations||[]).some(a=>a.ref===p.no&&!isOtherAlloc(a)))payOthers(x).forEach(a=>payOther.push(`<li>${esc(fmt(a.amount,x.cur))} for ${a.oref||a.ref?orefChip(a.oref||a.ref)+" ":""}<small class="status">${esc(coLabel(a.belongsTo))}${a.note?" — "+esc(a.note):""}</small> sent with ${refChip("payments",x.no)} ${pill("no fee","p-mute")}</li>`))});
 const sentWith=st.pays.filter(x=>x&&(x.allocations||[]).some(a=>a.ref===p.no&&isOtherAlloc(a))).map(x=>{const m=mainAllocOf(x);return`<li>${refChip("payments",x.no)} ${esc(fmt(allocAmount(x,p.no),x.cur))} for this order — sent with the ${m?refChip(colOfRef(m.ref)||"purchases",m.ref):"another"} payment (${esc(fmt(x.amount,x.cur))} sent)</li>`});
 const head=`Invoice total <b>${T(sp.invoiceTotal)}</b> = this order <b>${T(sp.thisOrder)}</b> <small class="status">(${parts.join(", ")})</small>${sp.othersSum?` + other charges <b>${T(sp.othersSum)}</b>:`:""}`;
 const own=r2(sp.thisOrder+(st.viaExtra||0));const tg=toGbp(own,cur,p.date);
 const views=sp.othersSum||st.via.length?`<div class="kv mixkv"><div><span>Supplier balance (whole invoice)</span><b>${T(st.outstandingCur)} to pay</b><small class="status" style="display:block">paid ${T(st.paidCur)}${st.viaUsed?` + ${T(st.viaUsed)} billed on other invoices`:""} of ${T(sp.invoiceTotal)}</small></div><div><span>This order's own cost</span><b>${T(own)}</b><small class="status" style="display:block">${tg==null?"no rate":gbp(tg)} at the order rate${st.viaExtra?` · incl. ${T(st.viaExtra)} billed on another invoice`:""}${sp.othersSum?` · excl. ${T(sp.othersSum)} for something else`:""}</small></div></div>`:"";
 const howT=`The invoice total is what ${esc(pname(p.party))} is owed for this PI — payments are matched against it. Lines and extra lines marked <b>belongs to</b> something else (another order, a shipment, a client, another company or brand, personal) are part of the invoice but <b>not</b> part of this order's cost: landed cost, stock value and product cost use only "this order". The China fee is worked out only on the fee-able parts (Setup › Lists › PI extra line kinds › “China fee applies”, or the flag on each row); amounts for something else get no fee unless you tick it. An amount for another order is shown on that order as “billed on ${esc(p.no)} invoice” and reduces what it still owes (anything beyond its balance is an extra cost of that order). Amounts for a client / company / brand / personal go to the Recharge list in Reports.`;
 return sec("Invoice breakdown",`<div class="note mixhead">${head}</div>${oth.length?`<ul class="mixlist">${oth.join("")}</ul>`:""}${via.length?`<div class="note">Also billed for this order on other invoices${st.viaUsed?` — settles ${T(st.viaUsed)} of what it still owed`:""}${st.viaExtra?` — ${T(st.viaExtra)} is an extra cost of this order`:""}:</div><ul class="mixlist">${via.join("")}</ul>`:""}${payOther.length?`<div class="note">With payments for this order we also paid:</div><ul class="mixlist">${payOther.join("")}</ul>`:""}${sentWith.length?`<div class="note">Paid together with another payment:</div><ul class="mixlist">${sentWith.join("")}</ul>`:""}${views}${how(howT,"How")}`,sp.othersSum?pill(`＋ other ${fmt(sp.othersSum,cur)}`,"p-warn"):"")}
function payRows(pays,ref,cur){return pays.slice().sort((a,b)=>(a.date||"")<(b.date||"")?-1:1).map(x=>{const a=ref?allocAmount(x,ref):+x.amount||0;const g=a*(payRate(x)||0);const[ct,cc]=payCheck(x);const counted=isCounted(x);const conv=cur&&x.cur!==cur&&counted?`<br><small class="status">${esc(poPayRows({no:ref,cur}).find(r=>r.no===x.no)?.conv||"")}</small>`:"";return[refChip("payments",x.no),fmtD(x.date),esc(L("payType",x.type)||"—"),`${fmt(a,x.cur)}${ref&&Math.abs(a-(+x.amount||0))>0.005&&!payOthers(x).length&&!(x.allocations||[]).some(z=>z.ref===ref&&isOtherAlloc(z))?`<br><small class="status">of ${fmt(x.amount,x.cur)}</small>`:""}${paySplitLine(x,ref)}${x.direction==="in"?" ↩":""}${conv}`,`${gbp(g)}${x.gbpActual!=null&&x.gbpActual!==""?'<br><small class="status">actual</small>':""}`,`${pill(ct,cc)}${counted?"":`<br><small class="status">not counted — ${esc(payWhyNot(x))}</small>`}`]})}
const PAY_HEADS=["No","Date","Type",{l:"Amount",n:1},{l:"£",n:1},"Check"];

/* ---------- renderDrawer ---------- */
const COL_LABEL={purchases:"Purchases",shipments:"Shipments",payments:"Payments",inspections:"Inspections",receipts:"Receipts",moves:"Stock moves",credits:"Credit notes",products:"Products",parties:"Parties",imports:"Imports"};
const recKey=r=>r?(r.no||r.code||r.sku||(r.p&&(r.p.sku||r.p.code||r.p.no))||r.id):"";
function drawerSiblings(d){const page=d.col==="products"&&S.view?.k==="stock"?"stock":d.col;const rows=(S.lastRows&&S.lastRows[page])||[];const ids=rows.map(recKey).filter(Boolean);return ids.includes(d.id)?ids:[]}
function drawerNav(d){const ids=drawerSiblings(d);const i=ids.indexOf(d.id);const pg=PAGES.includes(d.col)?d.col:(S.view?.k||"home");
 const cr=`<nav class="crumb dcrumb" aria-label="Breadcrumb"><button type="button" data-crumb="home">Home</button><span aria-hidden="true">›</span><button type="button" data-crumb="${esc(pg)}">${esc(COL_LABEL[d.col]||d.col)}</button><span aria-hidden="true">›</span><span aria-current="page">${esc(d.id)}</span></nav>`;
 const nav=ids.length>1?`<span class="dnav"><button type="button" class="btn sm" data-act="recnav" data-id="${esc(ids[i-1]||"")}" ${i>0?"":"disabled"} aria-label="Previous record" title="Previous in this list (Alt+↑)">‹ Prev</button><span class="status num">${i+1} / ${ids.length}</span><button type="button" class="btn sm" data-act="recnav" data-id="${esc(ids[i+1]||"")}" ${i<ids.length-1?"":"disabled"} aria-label="Next record" title="Next in this list (Alt+↓)">Next ›</button></span>`:"";
 return`<div class="dtop">${cr}${nav}</div>`}
